    n = len(digit_list)
    mid = n // 2
    left_side = digit_list[:mid]
    if digit_list == digit_list[::-1]:
        if n % 2 == 0:
            left_incremented = increment(left_side)
            digit_list = left_incremented + left_incremented[::-1]
        else:
            left_incremented = increment(left_side + [digit_list[mid]])
            digit_list = left_incremented[: mid + 1] + left_incremented[:mid][::-1]
    else:
        if n % 2 == 0:
